" http://127.0.0.1:$PORT/v1/files -H "Authorization: Bearer $KEY" \ -F purpose=batch -F file=@batch_input.jsonl -F target_model_names=bedrock-batch-claude HTTP 200 $ curl -sS -w "HTTP %{http_code}
" http://127.0.0.1:$PORT/v1/batches -H "Authorization: Bearer $KEY" \ -H "Content-Type: application/json" \ -d '{"input_file_id": "'"$FILE_ID"'", "endpoint": "/v1/chat/completions", "completion_window": "24h"}' HTTP 200 $ curl -sS -w "HTTP %{http_code}
